 function health(replays){const series=[];replays.forEach(({data,name},idx)=>{const max=data.input.player.hp??data.input.player.maxHp,enemyMax=data.input.enemy.hp??data.input.enemy.maxHp;for(const[side,hp]of [[0,max],[1,enemyMax]])series.push({name:name+(side?'敌人':'角色'),color:colors[side],dash:idx>0,points:[{time:'0',value:hp,label:'开打前',step:0,source:idx,inspectable:false},...data.executed.steps.map((s,i)=>({time:s.time,value:s.after[side],label:'第'+(i+1)+'个时刻；'+(side?'敌人':'角色'),step:i,source:idx}))]});});render('cgHealthChart',series,{title:'这场战斗的实际生命变化',yLabel:'生命',xLabel:'战斗时间',step:true,onPoint:p=>{if(p.source)return;const e=document.getElementById('cgBattleStep');e.value=p.step;e.onchange?.();}});}
