 async function openBattle(){if(busy||!selectedRun)return;const d=ConnectedCore.diagnose(selectedRun,selectedStage),b=d.actualBattle||selectedRun.battles.find(x=>x.stage===selectedStage);if(!b)return;lock(true);notice('正在还原这场实际战斗，不需要重填属性。');try{replay=await callWorker({type:'replay',result:selectedRun,stage:b.stage,attempt:b.attempt});by('cgBattle').hidden=false;by('cgBattleTitle').textContent=`第${b.stage}关，第${b.attempt}场：${outcome[b.outcome]}`;by('cgBattleSummary').textContent=`等级自动带入：${Object.entries(b.levels).map(([k,v])=>upgradeNames[k]+v).join('，')}。每场满血开始；此场实际编号${b.seed}。`;by('cgActors').innerHTML=['player','enemy'].map((side,i)=>`<div><h5>${i?'这关敌人':'当时的角色'}</h5><dl>${fields.map(([k,label])=>'<dt>'+label+'</dt><dd>'+f(percent.has(k)?num(replay.input[side][k])*100:replay.input[side][k])+'</dd>').join('')}</dl></div>`).join('');by('cgBattleStep').innerHTML=replay.executed.steps.map((x,i)=>`<option value="${i}">${time(x.time)}，双方剩余生命 ${f(x.after[0])} / ${f(x.after[1])}</option>`).join('');by('cgBattleStep').disabled=!replay.executed.steps.length;renderMoment();notice('已显示实际战斗记录；这里的属性来自该场开打前的等级。');}catch(e){notice(e.message,true);}finally{lock(false);}}
