 function validateStoredRuns(rs){if(!Array.isArray(rs)||rs.length>8)throw Error('结果样本数量不支持');for(const r of rs){if(![ConnectedCore.VERSION,ConnectedCore.CURRENT_VERSION].includes(r.version)||r.version!==r.inputGame?.version||r.format!=='idle-connected-result-v1'||r.ledger?.exactConserved!==true||!ConnectedCore.verifyLedger(r)||!Number.isInteger(r.seed)||r.seed<0||r.seed>4294967295||!Object.keys(statusNames).includes(r.status)||['battles','stages','events','purchases','waits','visits'].some(k=>!Array.isArray(r[k])))throw Error('结果版本或收支检查不匹配');ConnectedCore.compile(r.inputGame);}}
 function loadProject(data){if(data.format==='idle-connected-game-v1'){install(data);return;}if(!['idle-connected-workbench-results-v1','idle-connected-workbench-project-v1'].includes(data.format)||data.version!==ConnectedCore.VERSION)throw Error('这不是本版一体化游戏的配置或结果文件');ConnectedCore.compile(data.game);if(data.baseGame)ConnectedCore.compile(data.baseGame);if(data.baseRuns){validateStoredRuns(data.baseRuns);validateStoredRuns(data.candidateRuns);}const previousHistory=Array.isArray(data.history)?copy(data.history):[];for(const h of previousHistory){if(h.game)ConnectedCore.compile(h.game);if(h.baseRuns)validateStoredRuns(h.baseRuns);if(h.candidateRuns)validateStoredRuns(h.candidateRuns);}install(data.game);history=previousHistory;baseGame=data.baseGame?copy(data.baseGame):null;if(data.baseRuns){baseRuns=data.baseRuns;candidateRuns=data.candidateRuns;failures=data.failures||[];rejected=data.rejected||[];renderResults();show('results');}runSummary();const activeResult=candidateRuns[0]||baseRuns[0],historical=activeResult&&JSON.stringify(activeResult.inputGame)!==JSON.stringify(game);notice(historical?'已打开历史结果；它使用记录中的游戏快照，当前工作配置尚未完成重算。':'已载入同一游戏的配置'+(data.baseRuns?'和实际结果。':'；模拟过程需重新运行。'));}
 let battleChecks=[],playback=null,logPage=0;
