 function stopPlayback(){if(playback){clearInterval(playback);playback=null;}by('cgPlayBattle').textContent='播放过程';}
 selectRun=function(){stopPlayback();selectLegacy();if(!selectedRun)return;const a=baseRuns.find(r=>r.seed===selectedRun.seed),b=candidateRuns.find(r=>r.seed===selectedRun.seed);ConnectedCharts.progression(a||selectedRun,b||null);};
 openBattle=async function(){stopPlayback();if(!ConnectedV2.is(selectedRun?.inputGame)){await openLegacyBattle();if(replay){ConnectedCharts.health([{data:replay,name:'当前记录'}]);renderBattleLog();}return;}if(busy||!selectedRun)return;const d=ConnectedCore.diagnose(selectedRun,selectedStage),b=d.actualBattle||selectedRun.battles.find(x=>x.stage===selectedStage);if(!b)return;lock(true);try{replay=await callWorker({type:'replay',result:selectedRun,stage:b.stage,attempt:b.attempt});by('cgBattle').hidden=false;by('cgBattleTitle').textContent='第'+b.stage+'关，第'+b.attempt+'场：'+outcome[b.outcome];by('cgBattleSummary').textContent='等级自动带入：'+Object.entries(b.levels).map(([k,v])=>(upgradeNames[k]||k)+v).join('，')+'。每场满血；实际编号'+b.seed+'。';by('cgActors').innerHTML=['player','enemy'].map((side,i)=>'<div><h5>'+(i?'这关敌人':'当时角色')+'</h5><dl>'+ConnectedV2.fields(selectedRun.inputGame).map(([k,n])=>'<dt>'+escape(n)+'</dt><dd>'+f(replay.input[side][k])+'</dd>').join('')+'</dl></div>').join('');by('cgBattleStep').innerHTML=replay.executed.steps.map((s,i)=>'<option value="'+i+'">'+f(s.time)+'秒，生命'+f(s.after[0])+' / '+f(s.after[1])+'</option>').join('');by('cgBattleStep').disabled=!replay.executed.steps.length;renderMoment();const paired=selectedRun===candidateRuns.find(r=>r.seed===selectedRun.seed)?baseRuns.find(r=>r.seed===selectedRun.seed):candidateRuns.find(r=>r.seed===selectedRun.seed),series=[{data:replay,name:candidateRuns.includes(selectedRun)?'修改后':'修改前'}];if(paired?.battles.some(x=>x.stage===b.stage&&x.attempt===b.attempt)){const other=await callWorker({type:'replay',result:paired,stage:b.stage,attempt:b.attempt});series.push({data:other,name:candidateRuns.includes(paired)?'修改后':'修改前'});}ConnectedCharts.health(series);renderBattleLog();notice('实际生命、逐击记录和曲线使用同一场战斗；虚线仅在另一个方案确实打过对应场次时显示。');}catch(error){notice(error.message,true);}finally{lock(false);}};
 renderMoment=function(){if(replay?.input.format!=='multi-exact-battle-v2'){momentLegacy();return;}const i=Number(by('cgBattleStep').value)||0,s=replay.executed.steps[i];by('cgBattlePrev').disabled=i<=0;by('cgBattleNext').disabled=i>=replay.executed.steps.length-1;if(!s){by('cgBattleMoment').textContent='截止时还没有实际事件。';return;}by('cgBattleMoment').innerHTML='<p>'+f(s.time)+'秒：伤害前生命'+s.before.map(f).join(' / ')+'；伤害后'+s.afterDamage.map(f).join(' / ')+'；吸血后'+s.afterLeech.map(f).join(' / ')+'；回复后'+s.after.map(f).join(' / ')+'。</p>'+s.attacks.map(a=>'<p>'+(a.side?'敌人':'角色')+(a.critical?'暴击':'普通攻击')+(a.blocked?'，被格挡':'')+'：实际扣血'+f(a.actualHpLost)+'，吸血请求'+f(a.leechRequested)+'。</p><div class="scroll"><table><thead><tr><th>伤害</th><th>原始</th><th>增强/暴击后</th><th>护甲/抗性后</th><th>格挡后</th><th>实际扣血</th></tr></thead><tbody>'+ConnectedCore.multi.TYPES.filter(t=>selectedRun.inputGame.types[t]).map(t=>'<tr><td>'+ConnectedCore.multi.NAMES[t]+'</td>'+['raw','boosted','mitigated','final','actualHpLost'].map(k=>'<td>'+f(a.channels[t][k])+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>').join('');};
 function battleLog(){return (replay?.executed.steps||[]).flatMap((s,i)=>[...s.attacks.map(a=>({time:s.time,step:i,event:a.side?'enemy':'player',name:(a.side?'敌人':'角色')+(a.critical?'暴击':'攻击')+(a.blocked?' / 被格挡':''),actual:a.actualHpLost,playerHp:s.after[0],enemyHp:s.after[1],channels:a.channels})),...s.regen.flatMap((r,side)=>num(r.applied)>0?[{time:s.time,step:i,event:'regen',name:(side?'敌人':'角色')+'回复',actual:r.applied,playerHp:s.after[0],enemyHp:s.after[1]}]:[])]);}
 function renderBattleLog(){const filter=by('cgLogFilter').value,rows=battleLog().filter(x=>filter==='all'||x.event===filter),pages=Math.max(1,Math.ceil(rows.length/40));logPage=Math.max(0,Math.min(logPage,pages-1));by('cgLogRows').innerHTML=rows.slice(logPage*40,logPage*40+40).map(x=>'<tr><td>'+f(x.time)+'秒</td><td>'+x.name+'</td><td>'+f(x.actual)+'</td><td><button type="button" data-log-step="'+x.step+'">查看拆解</button></td></tr>').join('');by('cgLogPage').textContent=(logPage+1)+'/'+pages+'页，共'+rows.length+'条';by('cgLogPrev').disabled=!logPage;by('cgLogNext').disabled=logPage===pages-1;}
