 function enemySummary(input){const e=input.enemy,g=input.game,parts=['生命'+f(e.hp),'每秒'+f(e.frequency)+'次攻击'];if(g.types.physical)parts.push('物理'+f(e.physicalMin)+'–'+f(e.physicalMax));for(const t of ['fire','ice','lightning','poison'])if(g.types[t])parts.push(ConnectedCore.multi.NAMES[t]+f(e[t]));parts.push(g.mechanisms.armor?'护甲'+f(e.armor):'护甲机制关闭');parts.push(g.mechanisms.resistance?ConnectedCore.multi.TYPES.filter(t=>g.types[t]).map(t=>ConnectedCore.multi.NAMES[t]+'抗性'+f(num(e[t+'Resist'])*100)+'%').join('、'):'抗性机制关闭');return parts.join('；');}
