   const context=cross?'<p>旧页固定敌人模板 · 第'+selectedStage+'关角色等级 · 每组'+result.trials+'场</p>':'<p>第'+selectedStage+'关 · '+result.trials+'场重复战斗</p>',actual=[a,b].map((r,i)=>ConnectedCore.battleConfig(ConnectedCore.compile(r.inputGame).v,i?sb.levels:sa.levels,selectedStage,r.seed)),source='<p><strong>本关敌人</strong>：'+escape(enemyPair(actual))+'。</p>',templates=cross?result.rows.map(r=>'<p><strong>'+escape(r.name)+'</strong>：'+escape(enemyPair(r.inputs))+'。</p>').join(''):'';
   by('cgCheckResults').innerHTML=context+source+templates+'<div class="scroll"><table><thead><tr><th>敌人</th><th>方案</th><th>胜 / 死亡 / 超时 / 同归于尽</th><th>胜率与95%模拟区间</th><th>胜场平均 / 最慢10%时间</th></tr></thead><tbody>'+result.rows.flatMap(r=>['before','after'].map((side,i)=>{const s=r[side],times=s.wins?f(s.meanWinTime)+' / '+f(s.p90WinTime)+'秒':'没有胜场';return '<tr><td>'+escape(r.name)+'</td><td>'+(i?'修改后':'修改前')+'</td><td>'+[s.wins,s.deaths,s.timeouts,s.draws].join(' / ')+'</td><td>'+f(s.winRate*100)+'%（'+f(s.winLow*100)+'%至'+f(s.winHigh*100)+'%）</td><td>'+times+'</td></tr>';})).join('')+'</tbody></table></div>';
