 readForm=function(){if(!by('cgV2Editor'))return readLegacy();const g=ConnectedV2.read(copy(ConnectedV2.is(game)?game:ConnectedV2.blank())),number=id=>{const e=by(id),s=e.value.trim();if(!s||!Number.isFinite(Number(s))){e.setAttribute('aria-invalid','true');e.closest('details')?.setAttribute('open','');e.focus();throw Error('请填写'+e.closest('label').childNodes[0].textContent);}return s;};g.name=by('cgName').value.trim();if(!g.name){by('cgName').setAttribute('aria-invalid','true');by('cg-error-cgName').textContent='请先给这份游戏起个名称';by('cg-error-cgName').hidden=false;by('cgName').focus();throw Error('请填写游戏名称');}g.world.rewardBase=number('cg-rewardBase');g.world.rewardStep=number('cg-rewardStep');g.economy.costScale='1';g.economy.rewardScale='1';g.economy.initialCoins=number('cg-initialCoins');g.economy.incomePerSecond=number('cg-income');g.economy.incomeDuringCombat=by('cg-combatIncome').value==='true';g.behavior={mode:by('cg-behavior').value,visitHours:by('cg-hours').value.split(',').map(x=>Number(x.trim())),sessionMinutes:number('cg-session'),offlineCapHours:number('cg-cap')};g.rules={armorK:number('cg-armorK'),battleTimeoutSeconds:number('cg-timeout'),victoryDelaySeconds:number('cg-victoryDelay'),retryDelaySeconds:number('cg-retryDelay')};g.simulation={seeds:by('cg-seeds').value.split(',').map(x=>Number(x.trim())),observationSeconds:ConnectedCore.multiply(number('cg-budget'),'3600'),maxEvents:Number(number('cg-maxEvents')),maxBattles:Number(number('cg-maxBattles'))};g.goalUnits={completion:by('cgGoalUnit').value,wait:by('cgWaitUnit').value};for(const[id,key]of [['cgGoalMin','minCompletionSeconds'],['cgGoalMax','maxCompletionSeconds'],['cgGoalGap','maxGapSeconds'],['cgGoalVisit','stagesPerVisit']]){const s=by(id).value.trim();g.goals[key]=by('cgGoalMode').value==='pending'||!s?null:key==='stagesPerVisit'?Number(s):ConnectedCore.multiply(s,String(units[by(key==='maxGapSeconds'?'cgWaitUnit':'cgGoalUnit').value]));}ConnectedCore.compile(g);return g;};
