function selection(){return {run:by('cgRunSelect').value,stage:selectedStage};}
function applySelection(s){if(!s)return;if(Array.from(by('cgRunSelect').options).some(o=>o.value===s.run)){by('cgRunSelect').value=s.run;selectRun();}if(selectedRun&&Number.isInteger(s.stage)&&selectedRun.stages[s.stage-1]?.arrival!=null)showDiagnosis(s.stage);}
