function restoreSnapshot(s){({game,baseGame,baseRuns,candidateRuns,failures,rejected,history,battleChecks,appliedName}=copy(s));Object.assign(scrollPlaces,s.places||{});dirty=false;formReady=false;selectedRun=candidateRuns[0]||baseRuns[0]||null;if(selectedRun){renderResults();applySelection(s.selection);}}
function recordMatches(){return !!(searchRecord&&game&&(fingerprint(searchRecord.sourceGame)===fingerprint(game)||appliedUndo&&fingerprint(searchRecord.sourceGame)===fingerprint(appliedUndo.game)));}
function updateChrome(){
 by('cgGameTitle').textContent=game?.name||'选择一份游戏数据';by('cgGameTitle').title=by('cgGameTitle').textContent;let state=previewState?'预览方案'+previewState.number+' · 未应用':dirty?'编辑中 · 有未保存修改':appliedName?'已应用'+appliedName:game?'当前配置':'未载入';if(game&&!dirty&&!previewState)state+=' · '+(savedWorkspace?'已保存到本机':'未保存到本机');if(dirty&&(workspaceView==='results'||workspaceView==='solutions'))state+=' · 显示修改前记录';by('cgWorkspaceState').textContent=state;
 for(const[id,active]of [['cgDataTab',workspaceView==='data'],['cgRunTab',['results','simulation'].includes(workspaceView)],['cgResultsTab',workspaceView==='solutions']]){if(active)by(id).setAttribute('aria-current','page');else by(id).removeAttribute('aria-current');}
 actionBar.hidden=workspaceView==='empty';by('cgForm').inert=!!previewState;
 const primary=by('cgPrimary'),secondary=by('cgSecondary');primary.disabled=false;secondary.hidden=true;primary.textContent='开始整体检查';by('cgActionState').textContent=busy?(searching?'已算'+(searchRecord?.runs||0)+'次':'计算中…'):lastFeedback;
 if(busy){primary.textContent=searching?'停止搜索':'停止计算';primary.disabled=false;}
 else if(previewState){primary.textContent=workspaceView==='solutions'&&selectedChoice!==previewState.id?'预览选中方案':'应用这个方案';secondary.hidden=false;secondary.textContent='取消预览';}
 else if(dirty){primary.textContent='保存并运行';if(workspaceView!=='data')by('cgActionState').textContent='有未保存修改';}
 else if(workspaceView==='data')primary.textContent='保存并运行';
 else if(workspaceView==='solutions'){const row=searchRecord?.rows.find(x=>x.id===selectedChoice);primary.textContent=row&&recordMatches()?'预览选中方案':currentRuns().length?'查找解决方案':'先运行整体检查';if(searchRecord?.status==='already_meets'&&recordMatches()){primary.textContent='当前方案符合目标';primary.disabled=true;}if(['no_fault','conflict','insufficient_observation'].includes(searchRecord?.status)&&recordMatches())primary.textContent=searchRecord.status==='insufficient_observation'?'调整观察期':'调整目标或回访';secondary.hidden=!currentRuns().length;secondary.textContent='返回检查结果';}
 else if(workspaceView==='results')primary.textContent=searchRecord&&recordMatches()?'查看解决方案':'查找解决方案';
 if(!busy&&!previewState&&dirty){secondary.hidden=false;secondary.textContent='撤回未保存修改';}else if(!busy&&!previewState&&appliedUndo){secondary.hidden=false;secondary.textContent='撤销本次应用';}
 by('cgSave').disabled=!game||dirty||busy;by('cgManual').hidden=!baseRuns.length;by('cgComparisonPanel').hidden=by('cgComparison').hidden;by('cgShowBattle').disabled=busy||!selectedRun?.battles.some(b=>b.stage===selectedStage);
}
const navigateCore=show;show=function(view,{remember=true}={}){if(remember&&workspaceView!==view)scrollPlaces[workspaceView]=window.scrollY;workspaceView=view;navigateCore(view==='solutions'?'none':view);solutionView.hidden=view!=='solutions';updateChrome();if(scrollPlaces[view]!==undefined)window.scrollTo({top:scrollPlaces[view],behavior:'instant'});};
by('cgDataTab').onclick=()=>{if(!formReady)drawForm(!game);show('data');};by('cgRunTab').onclick=()=>show(currentRuns().length?'results':game?'simulation':'empty');by('cgResultsTab').onclick=()=>{prepareBounds();renderSearch();show('solutions');};
function summarizeResults(){const rows=candidateRuns.length?candidateRuns:baseRuns;if(!rows.length)return;const s=ConnectedSearch.stats(rows),budget=rows[0].inputGame.simulation.observationSeconds,stage=rows[0].inputGame.world.stageCount,planned=rows[0].inputGame.simulation.seeds.length;
 by('cgWhat').textContent=(rows.length<planned?'已算出'+rows.length+'/'+planned+'个编号；':'')+(s.completed===rows.length?stage+'关全部完成，最慢'+time(s.time):time(budget)+'内，'+s.completed+'/'+rows.length+'完成；停在第'+(s.lowest+1)+(s.highest!==s.lowest?'–'+(s.highest+1):'')+'关')+'；最长停滞'+time(s.gap)+'。';
 const misses=[['completion','完成周期'],['wait','最长停滞'],['visits','回访进展']].map(([k,n])=>({n,count:rows.filter(r=>r.goals[k]===false).length})).filter(x=>x.count);by('cgWhy').textContent=misses.length?'未达目标：'+misses.map(x=>x.n+' '+x.count+'/'+rows.length).join('、')+'。':'';
 if(candidateRuns.length){const a=ConnectedSearch.stats(baseRuns),b=s,changes=diffs(baseGame,game),cost=designTradeoff(baseGame,game)+onlineChange(baseGame,game);by('cgTradeoff').innerHTML=[['改动',changes.slice(0,3).join('；')+(changes.length>3?'；其余见完整前后数据':'')||'无'],['结果',a.completed+'/'+a.samples+' → '+b.completed+'/'+b.samples+'完成；最长停滞'+time(a.gap)+' → '+time(b.gap)],['代价',cost||'花费金币 '+pretty(a.spent)+' → '+pretty(b.spent)+'；购买次数 '+f(a.purchases)+' → '+f(b.purchases)]].map(([k,v])=>'<p class="cg-comparison-line"><strong>'+k+'</strong><span>'+escape(v)+'</span></p>').join('');}
}
const renderCore=renderResults;renderResults=function(){renderCore();summarizeResults();updateChrome();};
const diagnosisCore=showDiagnosis;showDiagnosis=function(stage){diagnosisCore(stage);if(selectedRun){const d=ConnectedCore.diagnose(selectedRun,stage);if(!d.unreached){by('cgBlockWhat').textContent=(d.passed?'这关已通过。':time(selectedRun.inputGame.simulation.observationSeconds)+'内未通过。')+'失败'+d.failures+'场，停滞'+time(d.seconds)+'。';}}updateChrome();};
