const saveCore=saveForm;saveForm=function(){const before=game?copy(game):null,ok=saveCore();if(ok){savedWorkspace=false;scrollPlaces.results=0;const changed=before?(ConnectedV2.is(before)&&ConnectedV2.is(game)?ConnectedV2.changes(before,game).length>0:fingerprint(before)!==fingerprint(game)):true;if(changed){appliedUndo=null;appliedName='';}}updateChrome();return ok;};
const shortInput=x=>String(Number(Number(x).toPrecision(12)));
const drawWorkspace=drawForm;drawForm=function(...args){drawWorkspace(...args);by('cgDataIntro').textContent='';for(const id of ['cg-budget','cg-session','cgGoalMin','cgGoalMax','cgGoalGap'])if(by(id)?.value!=='')by(id).value=shortInput(by(id).value);};
const readWorkspace=readForm;readForm=function(){const original=game,raw={budget:by('cg-budget').value,session:by('cg-session').value,min:by('cgGoalMin').value,max:by('cgGoalMax').value,gap:by('cgGoalGap').value,mode:by('cgGoalMode').value,unit:by('cgGoalUnit').value,wait:by('cgWaitUnit').value},next=readWorkspace();if(original){if(raw.budget===shortInput(num(original.simulation.observationSeconds)/3600))next.simulation.observationSeconds=original.simulation.observationSeconds;if(raw.session===shortInput(num(original.behavior.sessionMinutes)))next.behavior.sessionMinutes=original.behavior.sessionMinutes;for(const[key,field,unit]of [['minCompletionSeconds','min','unit'],['maxCompletionSeconds','max','unit'],['maxGapSeconds','gap','wait']]){const oldUnit=original.goalUnits?.[unit==='wait'?'wait':'completion']||'hours';if(raw.mode==='set'&&raw[unit]===oldUnit&&original.goals[key]!==null&&raw[field]===shortInput(num(original.goals[key])/units[oldUnit]))next.goals[key]=original.goals[key];}}ConnectedCore.compile(next);return next;};
