function optionsFromFormSafe(){try{return optionsFromForm();}catch{return null;}}
function validateSearch(r){return ConnectedSearch.validateRecord(r);}
function validateSnapshot(s){if(!s)return;ConnectedCore.compile(s.game);if(s.baseGame)ConnectedCore.compile(s.baseGame);validateStoredRuns(s.baseRuns);validateStoredRuns(s.candidateRuns);if(!Array.isArray(s.history)||!Array.isArray(s.failures))throw Error('工作区回退记录不完整');}
const loadCore=loadProject;loadProject=function(data){validateSearch(data.search);if(data.searchHistory&&!Array.isArray(data.searchHistory))throw Error('搜索历史格式不匹配');for(const r of data.searchHistory||[])validateSearch(r);validateSnapshot(data.applicationUndo);validateSnapshot(data.workspace?.preview?.original);loadCore(data);searchRecord=copy(data.search||null);searchHistory=copy(data.searchHistory||[]);selectedChoice=data.workspace?.selectedChoice||null;appliedName=typeof data.workspace?.appliedName==='string'?data.workspace.appliedName:'';appliedUndo=data.applicationUndo||null;previewState=data.workspace?.preview||null;pendingSearchOptions=data.searchOptions?copy(data.searchOptions):null;if(data.searchOptions){for(const[id,key]of [['cgSearchSeconds','seconds'],['cgSearchRuns','maxRuns'],['cgSearchEvents','maxEvents']])by(id).value=data.searchOptions[key];}if(data.workspace?.scrollPlaces)for(const[k,v]of Object.entries(data.workspace.scrollPlaces))if(['data','results','solutions','simulation','empty'].includes(k)&&Number.isFinite(v)&&v>=0)scrollPlaces[k]=v;by('cgSearchBounds').dataset.game='';by('cgSearchBounds').innerHTML='';prepareBounds();renderSearch();applySelection(data.workspace?.selection);if(data.workspace?.view==='solutions'&&searchRecord)show('solutions',{remember:false});else if(data.workspace?.view==='data'&&game){if(!formReady)drawForm(false);show('data',{remember:false});}updateChrome();};
function database(){return new Promise((resolve,reject)=>{const req=indexedDB.open('idle-connected-workspace',1);req.onupgradeneeded=()=>req.result.createObjectStore('workspace');req.onerror=()=>reject(req.error);req.onsuccess=()=>resolve(req.result);});}
by('cgSave').onclick=async()=>{if(dirty)return;try{const db=await database(),tx=db.transaction('workspace','readwrite');tx.objectStore('workspace').put(copy(project(true)),'current');await new Promise((resolve,reject)=>{tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});db.close();savedWorkspace=true;notice('工作区已保存到本机。');updateChrome();}catch(e){notice('本机保存失败，请导出完整结果：'+e.message,true);}};
by('cgRestore').onclick=async()=>{try{const db=await database(),tx=db.transaction('workspace','readonly'),req=tx.objectStore('workspace').get('current'),data=await new Promise((resolve,reject)=>{req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});db.close();if(data)loadProject(data);else{const raw=localStorage.getItem(stateKey);if(!raw)throw Error('没有本机存档');loadProject(JSON.parse(raw));}savedWorkspace=true;filesDialog.close();updateChrome();notice('工作区已恢复。');}catch(e){notice(e.message,true);}};
